/**
 * Helpers for mapping SAS log problems from console runs back to the editor
 * the code came from (posit-dev/positron-sas-extension#68). Kept free of
 * `vscode` imports so they can be unit tested.
 */

/**
 * Where console code sits in the editor it was run from, as character
 * offsets into the document text, or undefined if it can't be found (code
 * typed into the console, or generated by Positron Assistant).
 *
 * The code must appear verbatim (ignoring trailing whitespace). If it appears
 * more than once, the occurrence around the cursor wins, or else the closest
 * one before it, since Positron runs the statement at the cursor and may
 * already have moved the cursor past it.
 */
export function locateCodeInDocument(
  documentText: string,
  code: string,
  cursorOffset: number,
): { start: number; end: number } | undefined {
  const needle = code.replace(/\s+$/, "");
  if (needle.trim() === "") {
    return undefined;
  }
  const starts: number[] = [];
  for (
    let i = documentText.indexOf(needle);
    i !== -1;
    i = documentText.indexOf(needle, i + 1)
  ) {
    starts.push(i);
  }
  if (starts.length === 0) {
    return undefined;
  }
  const at = (start: number) => ({ start, end: start + needle.length });
  if (starts.length === 1) {
    return at(starts[0]);
  }
  const containing = starts.find(
    (s) => s <= cursorOffset && cursorOffset <= s + needle.length,
  );
  if (containing !== undefined) {
    return at(containing);
  }
  const before = starts.filter((s) => s + needle.length <= cursorOffset);
  return at(before.length > 0 ? before[before.length - 1] : starts[0]);
}

/**
 * The code an editor Run sends to the console: the non-empty selections
 * joined by newlines (as upstream's getSelectedCode does), or else the
 * whole document.
 */
export function editorCodeToRun(
  documentText: string,
  selectedTexts: readonly string[],
): string {
  const selected = selectedTexts.filter((text) => text !== "");
  return selected.length > 0 ? selected.join("\n") : documentText;
}
